function revoke(){if(!removing.value)return;const id=removing.value.id;void run(async()=>{await props.api('api-keys/'+id,'DELETE');removing.value=null;notice.value='API ��Կ��ɾ����������������ʧЧ���б��������ѳ�����Ŀ��';await reload()})}
async function copy(){try{await navigator.clipboard.writeText(secret.value);notice.value='�Ѹ��� API ��Կ'}catch{error.value='���ֶ�ѡ�񲢸�����Կ'}}
</script>
