<div v-if="editing" class="modal-backdrop"><form class="modal" role="dialog" aria-modal="true" aria-label="API Ȩ������" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'�޸�':'����'}} API ��Կ</h2><button class="secondary" type="button" @click="editing=null">�ر�</button></div><div class="form-content"><p v-if="error" class="error">{{error}}</p><div class="fields"><label>��;����<input v-model="editing.name" required maxlength="100" placeholder="����ǰ�� / Telegram Bot"></label><label>��������<input v-model="editing.expires_at" type="date" required></label><label>ÿ������������<input v-model.number="editing.rate_limit" type="number" min="1" max="600" required></label></div><h3>Ȩ��ģ��</h3><div class="subnav"><button class="secondary" type="button" @click="preset('read')">ֻ�����</button><button class="secondary" type="button" @click="preset('telegram')">�������û�����</button><button class="secondary" type="button" @click="preset('airport')">�����������</button><button class="secondary" type="button" @click="preset('custom')">��գ��Զ���</button></div><div class="choice-list"><label v-for="s in scopes" :key="s.id"><input v-model="editing.scopes" type="checkbox" :value="s.id"><span>{{s.name}}<small class="block-muted">{{s.id}}{{s.sensitive?' �� ����Ȩ��':''}}</small></span></label></div><p class="muted">�������롢����ƾ�ݡ���Դ IP���޸����÷ֱ���Ȩ��API ��Կ���ܴ���������Կ��Ҳ���ܵ���������Ȩ�����ӿڡ�����ǰ�˻�����վ����������д׼ȷ�� HTTPS ��Դ��</p></div><div class="modal-footer"><button class="secondary" type="button" @click="editing=null">ȡ��</button><button class="primary" :disabled="busy||!editing.scopes.length">����Ȩ��</button></div></form></div><div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="form-content"><h2>ɾ�� {{removing.name}}��</h2><p>ʹ�ô���Կ�ĺ������������ʧЧ����Կ��¼���Ӻ�̨ɾ�����������ɻָ�����Ҫ���´�����Կ��</p><p v-if="error" class="error">{{error}}</p></div><div class="modal-footer"><button class="secondary" @